import numpy as np
def read_xyz(fn):
    lines = open(fn).read().splitlines()
    n = int(lines[0])
    elems, pos = [], []
    for l in lines[2:2+n]:
        p = l.split()
        elems.append(p[0]); pos.append([float(p[1]),float(p[2]),float(p[3])])
    return elems, np.array(pos)
e, pos = read_xyz('gfn2_opt2.xyz')
h55 = pos[55]  # atom index 55 (0-based) = H55 label
for k in [6,7,0,1]:
    print('dist H(55)-',e[k],k, round(np.linalg.norm(h55-pos[k]),3))
# also check all H on mu-methyls C6(54,55,56) and C7(57,58,59)
for hi in [54,55,56]:
    print('H',hi,'on C6 dist:', round(np.linalg.norm(pos[hi]-pos[6]),3))
for hi in [57,58,59]:
    print('H',hi,'on C7 dist:', round(np.linalg.norm(pos[hi]-pos[7]),3))
